-- Juniper Counter, a duckgen dataset on the public bucket (S tier)
SET s3_region = 'us-east-1';
SET VARIABLE cafe = 's3://us-prd-motherduck-open-datasets/duckgen/'
    || 'cafe-juniper-decisions/20261025-a5155411-s-r1/tables/';

FROM read_parquet(getvariable('cafe') || 'item_daily/*.parquet')
LIMIT 5;

CREATE SHARE cafe_shop_managers FROM cafe (ACCESS RESTRICTED)
WITH SECURE VIEW REPLACES item_daily AS (
    SELECT shop_id, business_date, item_id,
           sold_units, revenue_cents      -- no cost or margin columns
    FROM item_daily
    WHERE shop_id IN (
        SELECT shop_id FROM shop_access WHERE member = current_user
    )
);
